#include <stdio.h>
int main(void) {
    int n = 0;
    int stop = 5;
    int sum = 0;
    for (int i = 1; i <= n; i = i + 1) {
        if (i > stop) {
            break;
        }
        if (i % 2 == 0) {
            continue;
        }
        sum = sum + i;
    }
    printf("%d\n", sum);
    return 0;
}
